            q(189, "Transformers", "The primary winding of a current transformer is always connected in what manner within the power system network?", listOf("In series with the high-power line whose current loop is being measured", "In parallel across the main system grid distribution conductors", "Directly linked to sub-station neutral grounding copper stakes", "Connected to a specialized tertiary stabilizing loop stage"), "In series with the high-power line whose current loop is being measured"),
            q(190, "DC Machines", "The speed-torque characteristic curve profile of an industrial DC shunt motor is characterized as a:", listOf("Slightly drooping straight line path", "Rapidly rising parabolic curve line", "Rectangular hyperbola asymptote track", "Perfect horizontal constant speed tracking"), "Slightly drooping straight line path"),
            q(191, "Transformers", "A power transformer winding insulation design uses a graded insulation layout. This approach is highly valid when the neutral terminal point is:", listOf("Permanently and solidly grounded to the earth network", "Left entirely isolated and ungrounded", "Grounded via a heavy current limiting inductive reactor", "Switched out periodically during high system load surges"), "Permanently and solidly grounded to the earth network"),
            q(192, "Transformers", "What type of three-phase transformer setup is highly prone to severe voltage distortion if loaded with an unbalanced single-phase line-to-neutral load?", listOf("Star-Star (Y-Y) connection bank without primary neutral tracking line link", "Delta-Star (D-Y) connected four-wire system panel setup", "Star-Delta (Y-D) step down system structural module", "Open-Delta (V-V) connected transformer setup stage"), "Star-Star (Y-Y) connection bank without primary neutral tracking line link"),
            q(193, "DC Machines", "The physical process of commutation in a DC machine results in a delayed current reversal due to the presence of:", listOf("Reactance voltage induced inside the short-circuited coil loop", "High contact resistance across the graphite carbon block faces", "Armature cross-magnetization field profile shifts", "Eddy current paths across the frame iron boundaries"), "Reactance voltage induced inside the short-circuited coil loop"),
            q(194, "DC Machines", "An over-compounded DC generator has its series field turns adjusted during design to ensure that full-load terminal voltage is:", listOf("Higher than the no-load terminal voltage value", "Exactly equal to the no-load terminal voltage value", "Lower than the no-load terminal voltage value", "Equal to zero magnitude value under overload short circuits"), "Higher than the no-load terminal voltage value"),
            q(195, "Induction Machines", "The crawling phenomenon in an industrial 3-phase squirrel-cage induction motor often pins its steady state speed to roughly which synchronous fraction?", listOf("1 / 7 of normal synchronous mechanical speed", "1 / 3 of normal synchronous mechanical speed", "1 / 5 of normal synchronous mechanical speed", "Half of normal rated mechanical operating speed"), "1 / 7 of normal synchronous mechanical speed"),
            q(196, "Induction Machines", "The breakdown mechanical output torque of a 3-phase induction motor operating at constant supply frequency scales as:", listOf("Directly proportional to the square of stator supply voltage (V^2)", "Directly proportional to the stator supply voltage value (V)", "Inversely proportional to stator supply voltage metrics (1/V)", "Independent of any stator input supply voltage configurations"), "Directly proportional to the square of stator supply voltage (V^2)"),
            q(197, "Synchronous Machines", "The operating torque angle value (δ) of a salient-pole synchronous generator under maximum load conditions is typically:", listOf("Less than 90 electrical degrees due to additional reluctance power components", "Exactly 90 electrical degrees under all loading profiles", "Greater than 90 electrical degrees due to core saturation factors", "Equal to 45 electrical degrees under flat voltage regulation modes"), "Less than 90 electrical degrees due to additional reluctance power components"),
            q(198, "Synchronous Machines", "The field excitation circuit loop of a standard utility-scale three-phase synchronous alternator is supplied via which energy source?", listOf("A reliable direct current (DC) source or brush-less exciter unit", "A single phase alternating current distribution step down link", "A direct connection to the generator high voltage stator output taps", "A separate permanent magnetic variable speed induction drive grid"), "A reliable direct current (DC) source or brush-less exciter unit"),
            q(199, "Transformers", "The phase displacement difference between the primary phase voltage and secondary phase voltage waves in an ideal single-phase transformer is exactly:", listOf("180 electrical degrees phase shifted", "0 electrical degrees (perfectly in-phase alignment)", "90 electrical degrees orthogonal configuration", "Variable depending on the external load power factor profile"), "180 electrical degrees phase shifted"),
            q(200, "Synchronous Machines", "The synchronous reactance of an alternator evaluated from the open-circuit and short-circuit characteristics at rated field excitation gives what kind of value?", listOf("A saturated synchronous reactance value, which is lower than unsaturated values", "An unsaturated synchronous reactance value, which is higher than actual", "The true absolute Potier leakage reactance matrix value directly", "An infinite reactance value due to perfect short circuit tracking loops"), "A saturated synchronous reactance value, which is lower than unsaturated values")
        )
    }

    private fun q(
        id: Int,
        subdomain: String,
        question: String,
        options: List<String>,
        answer: String
    ): GateQuestion {
        val topicId = when (subdomain) {
            "Transformers" -> "em_transformers"
            "DC Machines" -> "em_dc"
            "Induction Machines" -> "em_induction"
            "Synchronous Machines" -> "em_synchronous"
            else -> "em_transformers"
        }

        val subtopicId = when (subdomain) {
            "Transformers" -> {
                if (question.contains("three-phase", ignoreCase = true) ||
                    question.contains("3-phase", ignoreCase = true) ||
                    question.contains("autotransformer", ignoreCase = true) ||
                    question.contains("auto-transformer", ignoreCase = true) ||
                    question.contains("parallel", ignoreCase = true) ||
                    question.contains("Scott", ignoreCase = true) ||
                    question.contains("teaser", ignoreCase = true) ||
                    question.contains("Delta-Star", ignoreCase = true) ||
                    question.contains("open-delta", ignoreCase = true) ||
                    question.contains("V-V", ignoreCase = true) ||
                    question.contains("Sumpner", ignoreCase = true) ||
                    question.contains("Buchholz", ignoreCase = true) ||
                    question.contains("tertiary", ignoreCase = true)
                ) {
                    "em_trans_three_phase"
                } else {
                    "em_trans_single_phase"
                }
            }
            "DC Machines" -> {
                if (question.contains("speed control", ignoreCase = true) ||
                    question.contains("commutation", ignoreCase = true) ||
                    question.contains("commutator", ignoreCase = true) ||
                    question.contains("compensating", ignoreCase = true) ||
                    question.contains("armature reaction", ignoreCase = true) ||
                    question.contains("Ward-Leonard", ignoreCase = true) ||
                    question.contains("interpole", ignoreCase = true) ||
                    question.contains("carbon brush", ignoreCase = true) ||
                    question.contains("GNA", ignoreCase = true) ||
                    question.contains("MNA", ignoreCase = true)
                ) {
                    "em_dc_reaction_control"
                } else {
                    "em_dc_generators_motors"
                }
            }
            "Induction Machines" -> {
                if (question.contains("single-phase", ignoreCase = true) ||
                    question.contains("single phase", ignoreCase = true) ||
                    question.contains("double-revolving", ignoreCase = true) ||
                    question.contains("split-phase", ignoreCase = true) ||
                    question.contains("shaded-pole", ignoreCase = true) ||
                    question.contains("capacitor-run", ignoreCase = true) ||
                    question.contains("capacitor-start", ignoreCase = true) ||
                    question.contains("centrifugal switch", ignoreCase = true)
                ) {
                    "em_induction_single_phase"
                } else {
                    "em_induction_three_phase"
                }
            }
            "Synchronous Machines" -> {
                if (question.contains("alternator", ignoreCase = true) ||
                    question.contains("generator", ignoreCase = true) ||
                    question.contains("salient", ignoreCase = true) ||
                    question.contains("cylindrical", ignoreCase = true) ||
                    question.contains("pitch factor", ignoreCase = true) ||
                    question.contains("distribution factor", ignoreCase = true) ||
                    question.contains("regulation", ignoreCase = true) ||
                    question.contains("Potier", ignoreCase = true) ||
                    question.contains("EMF method", ignoreCase = true) ||
                    question.contains("MMF method", ignoreCase = true) ||
                    question.contains("synchronizing power", ignoreCase = true) ||
                    question.contains("infinite bus", ignoreCase = true) ||
                    question.contains("prime mover", ignoreCase = true)
                ) {
                    "em_synchronous_generators"
                } else {
                    "em_synchronous_motors"
                }
            }
            else -> "em_trans_single_phase"
        }

        val correctIdx = options.indexOf(answer).let { if (it == -1) 0 else it }

        val difficulty = when (id % 3) {
            0 -> "Easy"
            1 -> "Medium"
            else -> "Hard"
        }

        val formulas = when (subdomain) {
            "Transformers" -> "x = sqrt(P_i / P_cu_fl)"
            "DC Machines" -> "E_b = V - I_a * R_a"
            "Induction Machines" -> "N_s = 120 * f / P, s = (N_s - N_r) / N_s"
            "Synchronous Machines" -> "N_s = 120 * f / P"
            else -> ""
        }

        val explanationText = "Based on fundamental $subdomain concepts. The correct choice is: '$answer'. " +
            when (subdomain) {
                "Transformers" -> "Evaluates standard transformer efficiencies, equivalent circuits, and open/short-circuit test parameter bounds."
                "DC Machines" -> "Addresses EMF equations, field control, torque characteristics, and mechanical power developed under load."
                "Induction Machines" -> "Addresses rotating fields, slip-torque characteristics, double-revolving field theory, and starting methods."
                "Synchronous Machines" -> "Covers cylindrical/salient pole models, V-curves, synchronous condenser operations, and power angle equations."
                else -> ""
            }

        return GateQuestion(
            id = "em_q_$id",
            subjectId = "electrical_machines",
            topicId = topicId,
            subtopicId = subtopicId,
            year = 2020 + (id % 7),
            questionText = question,
            questionType = QuestionType.MCQ,
            options = options,
            correctOptions = listOf(correctIdx),
            correctNumericalRange = null,
            explanation = explanationText,
            formulasUsed = formulas,
            shortcutTricks = "Analyze dimensions, signs, and asymptotic limits of standard formulas.",
            relatedConcepts = "Electrical machines, magnetic modeling, $subdomain",
            difficulty = difficulty
        )
    }
}
